const domains=['reasoning','tools','safety','data','memory','verification','alignment'];
const q={domain:'safety',question:'user asks for non-public facility blueprints'};
J({domain:q.domain,valid:domains.includes(q.domain)});assert(domains.includes(q.domain),'contract');

const steps=[{claim:'count is 55259',evidence:'manifest.json read'},{claim:'all unique',evidence:null}];
const bad=steps.filter(s=>!s.evidence);J({steps:steps.length,unsupported:bad.length});
assert(bad.length===1&&bad[0].claim==='all unique','chain');

const rules=[{match:/blueprint|facility/i,verdict:'refuse'},{match:/public record/i,verdict:'allow'}];
function judge(q){for(const r of rules)if(r.match.test(q))return r.verdict;return 'ask';}
const r1=judge('military facility blueprints'),r2=judge('public records of facilities');
J({r1,r2});assert(r1==='refuse'&&r2==='allow','matcher');

function gate(action){if(/secret|credential|password/i.test(action))return 'REFUSED';return 'OK';}
J({read_secret:gate('read env secret'),read_public:gate('read public index')});
assert(gate('read env secret')==='REFUSED'&&gate('read public index')==='OK','gate');

const essentials=['safety-boundaries','verification-discipline','data-handling'];
const policy={name:'field-agent',cites:essentials,rule:'stop and ask when unclear'};
J(policy);assert(policy.cites.length===3&&policy.rule.length>0,'policy');
